// 1:1 port of firmware/components/effects/effects.cpp. Keep the two in lockstep; the golden
// vectors in packages/protocol/test-vectors/effects/ are generated by the C++ and checked here.
import { type RGB, hash32, hsv16, lerp8, lerpRgb, periodMs, phase16, posQ16, scaleRgb, sin16 } from "./math8";

export interface EffectParams {
  speed: number;
  intensity: number;
  colors: RGB[];
  seed: number;
  duration_ms: number;
}

type RenderFn = (p: EffectParams, t: number, n: number, out: RGB[]) => void;

function fill(out: RGB[], n: number, c: RGB): void {
  for (let i = 0; i < n; i++) out[i] = c;
}

const solid: RenderFn = (p, _t, n, out) => fill(out, n, p.colors[0]!);

const breathe: RenderFn = (p, t, n, out) => {
  const per = periodMs(p.speed, 20000, 2000);
  const ph = phase16(t, per);
  const s = sin16((ph + 49152) & 0xffff);
  const level = (s + 32768) >> 8;
  const scale = 255 - Math.floor((p.intensity * (255 - level)) / 255);
  fill(out, n, scaleRgb(p.colors[0]!, scale));
};

const gradient: RenderFn = (p, t, n, out) => {
  const nc = p.colors.length;
  if (nc <= 1) return fill(out, n, p.colors[0]!);
  const off = p.speed ? Math.floor((t * p.speed) / 16) % 65536 : 0;
  const seg = nc - 1;
  for (let i = 0; i < n; i++) {
    const x = posQ16(i, n);
    let u: number;
    if (!p.speed) u = x;
    else {
      const w = ((x >> 1) + off) & 0xffff;
      u = w < 32768 ? w * 2 : (65535 - w) * 2;
    }
    const sc = u * seg;
    const idx = sc >> 16;
    const f = (sc >> 8) & 0xff;
    out[i] = lerpRgb(p.colors[idx]!, p.colors[idx + 1]!, f);
  }
};

const cycle: RenderFn = (p, t, n, out) => {
  const per = periodMs(p.speed, 60000, 2000);
  fill(out, n, hsv16(phase16(t, per), p.intensity, 255));
};

const rainbow: RenderFn = (p, t, n, out) => {
  const per = periodMs(p.speed, 30000, 2000);
  const base = phase16(t, per);
  for (let i = 0; i < n; i++) {
    const h = (base + ((posQ16(i, n) * p.intensity) >> 8)) & 0xffff;
    out[i] = hsv16(h, 255, 255);
  }
};

const candle: RenderFn = (p, t, n, out) => {
  const step = 40 + Math.floor(((255 - p.speed) * 160) / 255);
  const k = Math.floor(t / step);
  const fr = Math.floor(((t % step) * 256) / step);
  const gstep = step * 4;
  const gk = Math.floor(t / gstep);
  const gfr = Math.floor(((t % gstep) * 256) / gstep);
  const g = lerp8(hash32(p.seed, 0xffffffff, gk) & 0xff, hash32(p.seed, 0xffffffff, gk + 1) & 0xff, gfr);
  const gdip = (g * g) >> 8;
  for (let i = 0; i < n; i++) {
    const v = lerp8(hash32(p.seed, i, k) & 0xff, hash32(p.seed, i, k + 1) & 0xff, fr);
    const dip = (((v * v) >> 8) + gdip) >> 1;
    const scale = 255 - Math.floor((p.intensity * dip) / 255);
    out[i] = scaleRgb(p.colors[0]!, scale);
  }
};

const twinkle: RenderFn = (p, t, n, out) => {
  const len = 2600 - Math.floor((p.speed * 2200) / 255);
  const nc = p.colors.length;
  for (let i = 0; i < n; i++) {
    const offset = hash32(p.seed, i, 0x7a11) % len;
    const tt = t + offset;
    const k = Math.floor(tt / len);
    const pos = tt % len;
    const h = hash32(p.seed, i, k);
    if ((h & 0xff) >= p.intensity) {
      out[i] = [0, 0, 0];
      continue;
    }
    let level = 2 * pos < len ? Math.floor((pos * 510) / len) : Math.floor(((len - pos) * 510) / len);
    if (level > 255) level = 255;
    out[i] = scaleRgb(p.colors[(h >>> 8) % nc]!, level);
  }
};

const SUNRISE_STOPS: { pos: number; c: RGB }[] = [
  { pos: 0, c: [0x00, 0x00, 0x00] },
  { pos: 13107, c: [0x40, 0x00, 0x00] },
  { pos: 32768, c: [0xff, 0x30, 0x00] },
  { pos: 49152, c: [0xff, 0x8c, 0x20] },
  { pos: 65535, c: [0xff, 0xd8, 0xa8] },
];

const sunrise: RenderFn = (p, t, n, out) => {
  const dur = p.duration_ms ? p.duration_ms : 1800000;
  const pr = t >= dur ? 65535 : Math.floor((t * 65535) / dur);
  let j = 0;
  while (j < 3 && pr > SUNRISE_STOPS[j + 1]!.pos) j++;
  const a = SUNRISE_STOPS[j]!;
  const b = SUNRISE_STOPS[j + 1]!;
  const f = Math.floor(((pr - a.pos) * 255) / (b.pos - a.pos));
  fill(out, n, lerpRgb(a.c, b.c, f));
};

const syncTest: RenderFn = (_p, t, n, out) => fill(out, n, t % 1000 < 20 ? [255, 255, 255] : [0, 0, 0]);

export const RENDERERS: Record<string, RenderFn> = {
  solid,
  breathe,
  gradient,
  cycle,
  rainbow,
  candle,
  twinkle,
  sunrise,
  sync_test: syncTest,
};

/**
 * Renders `n` pixels of an effect at `t` ms after its epoch (t < 0 is treated as 0).
 * Unknown ids render as solid.
 */
export function renderEffect(id: string, params: EffectParams, t: number, n: number): RGB[] {
  const out: RGB[] = new Array(n);
  const fn = RENDERERS[id] ?? solid;
  const colors = params.colors.length ? params.colors : [[255, 180, 107] as RGB];
  fn({ ...params, colors }, Math.max(0, Math.floor(t)), n, out);
  return out;
}
